    def test_factory_generate_without_params_uses_defaults(self, seeded_factory):
        """Factory should inject type-appropriate default params."""
        spec = seeded_factory.generate(FaultType.LATENCY_SPIKE)
        assert "latency_ms" in spec.params or "jitter_ms" in spec.params


