class TestPropertyBased:
    """Deterministic property checks without external dependencies."""

    @pytest.mark.parametrize("fault_type", list(FaultType))
    def test_round_trip_all_fault_types(self, fault_type):
        """Every fault type must survive serialization round-trip."""
        spec = FaultSpec(fault_type=fault_type, params={"key": "value"})
        restored = FaultSpec.from_dict(spec.to_dict())
        assert restored == spec

    @pytest.mark.parametrize("seed", [0, 1, 42, 12345, 2**31 - 1])
    def test_factory_determinism_across_seeds(self, seed):
        """Same seed must always produce identical output."""
        factory_a = FaultFactory(seed=seed)
        factory_b = FaultFactory(seed=seed)
        for _ in range(10):
            spec_a = factory_a.generate(FaultType.MESSAGE_LOSS)
            spec_b = factory_b.generate(FaultType.MESSAGE_LOSS)
            assert spec_a == spec_b

    def test_timestamp_monotonicity_across_types(self, seeded_factory):
        """Timestamps must be strictly increasing across mixed generation."""
        timestamps = []
        for fault_type in FaultType:
            spec = seeded_factory.generate(fault_type)
            timestamps.append(spec.timestamp)
        assert timestamps == sorted(timestamps)
        assert len(set(timestamps)) == len(timestamps)

    def test_random_distribution_is_not_constant(self):
        """Factory without seed should produce varied output."""
        factory = FaultFactory()
        specs = [factory.generate(FaultType.LATENCY_SPIKE) for _ in range(100)]
        timestamps = [spec.timestamp for spec in specs]
        assert len(set(timestamps)) > 90  # high entropy expected


