class TestIntegration:
    """End-to-end scenarios combining multiple components."""

    def test_full_workflow_yaml(self, tmp_path):
        """Create, export, import, and validate a fault scenario."""
        factory = FaultFactory(seed=2024)
        specs = factory.generate_batch(FaultType.NETWORK_PARTITION, count=3)

        # Export all to YAML
        for i, spec in enumerate(specs):
            spec.to_yaml(tmp_path / f"fault_{i}.yaml")

        # Import and validate
        for i, spec in enumerate(specs):
            restored = FaultSpec.from_yaml(tmp_path / f"fault_{i}.yaml")
            assert restored == spec

    def test_full_workflow_json(self, tmp_path):
        """Create, export, import, and validate a fault scenario."""
        factory = FaultFactory(seed=2024)
        specs = factory.generate_batch(FaultType.BYZANTINE_EQUIVOCATION, count=2)

        for i, spec in enumerate(specs):
            spec.to_json(tmp_path / f"fault_{i}.json")

        for i, spec in enumerate(specs):
            restored = FaultSpec.from_json(tmp_path / f"fault_{i}.json")
            assert restored == spec

    def test_mixed_fault_scenario(self, seeded_factory):
        """Generate a realistic mixed-fault scenario."""
        scenario = []
        scenario.append(seeded_factory.generate(FaultType.NETWORK_PARTITION, node_id="n1", target_node_id="n2"))
        scenario.append(seeded_factory.generate(FaultType.MESSAGE_LOSS, node_id="n3", params={"rate": 0.1}))
        scenario.append(seeded_factory.generate(FaultType.NODE_CRASH, node_id="n4"))
        scenario.append(seeded_factory.generate(FaultType.CLOCK_SKEW, node_id="n5", params={"offset_ms": 500}))

        assert len(scenario) == 4
        assert all(isinstance(spec, FaultSpec) for spec in scenario)
        assert scenario[0].target_node_id == "n2"
        assert scenario[1].params["rate"] == 0.1
        assert scenario[2].node_id == "n4"
        assert scenario[3].params["offset_ms"] == 500

    def test_scenario_serialization_round_trip(self, seeded_factory, tmp_path):
        """Serialize an entire scenario and restore it."""
        scenario = seeded_factory.generate_batch(FaultType.MESSAGE_REORDER, count=5)
        scenario_file = tmp_path / "scenario.json"

        with open(scenario_file, "w") as f:
            json.dump([spec.to_dict() for spec in scenario], f)

        with open(scenario_file, "r") as f:
            loaded_data = json.load(f)

        restored = [FaultSpec.from_dict(data) for data in loaded_data]
        assert restored == scenario


